/* @lc app=leetcode id=2245 lang=kotlin */ class Solution { fun cnt(x: Int, p: Int): Int = generateSequence(x) { it / p }.takeWhile { it % p == 0 }.count() fun sub(p: Pair<Int, Int>, q: Pair<Int, Int>) = p.first - q.first to p.second - q.second fun maxTrailingZeros(grid: Array<IntArray>): Int = grid.size.let { m -> grid[0].size.let { n -> Array(m) { i -> Array(n) { j -> cnt(grid[i][j], 2) to cnt(grid[i][j], 5) } }.let { a -> Array(m) { i -> grid[i].indices.runningFold(0 to 0) { (s2, s5), j -> s2 + a[i][j].first to s5 + a[i][j].second } }.let { row -> Array(n) { j -> grid.indices.runningFold(0 to 0) { (s2, s5), i -> s2 + a[i][j].first to s5 + a[i][j].second } }.let { col -> (0 until m * n).maxOf { k -> (k / n).let { i -> (k % n).let { j -> listOf(row[i][j + 1], sub(row[i][n], row[i][j])).flatMap { h -> listOf(col[j][i + 1], sub(col[j][m], col[j][i])).map { v -> minOf(h.first + v.first - a[i][j].first, h.second + v.second - a[i][j].second) } }.max() } } } } } } } } }